{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C02"],
      "claim": "Biperiden, a lipophilic basic CNS drug, crosses the BBB without difficulty with a brain-to-plasma ratio of 7–12, supporting meaningful CNS access for the similarly lipophilic basic amine scaffold of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Methylphenidate shows a rat brain-to-plasma Kp of 10.6–11.2 after intraperitoneal administration, demonstrating high brain distribution for a small lipophilic basic drug, directly transferable to the query's CNS exposure profile.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Mianserin, a tricyclic basic amine, has a rat logBB of 0.99 and is classified as a good brain penetrant, providing strong evidence that the query's tricyclic phenothiazine-like basic amine also achieves meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Blonanserin, a lipophilic CNS antipsychotic, shows a human brain/plasma concentration ratio of 3.38 by PET occupancy, indicating good BBB permeability and supporting the query's phenothiazine antipsychotic-like structure as CNS-penetrant.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Benztropine, another lipophilic basic CNS agent, shows clear brain uptake in humans and baboons by PET, reinforcing that the structural class represented by the query reliably crosses the blood-brain barrier.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a lipophilic, basic phenothiazine derivative. All highly transferable experimental analogues are direct CNS penetrants with brain/plasma ratios above 1 or clear PET brain uptake, and no contradictory evidence was retrieved. Therefore the query is predicted to have meaningful CNS access after systemic administration.",
  "evidence_gaps": [
    "No direct in vivo brain penetration measurement is available for the exact query molecule.",
    "Efflux transporter status was not explicitly measured for the query, but the consistently positive brain/plasma ratios in close analogues indicate adequate net CNS access."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

